const tasks = await query('com.example.type.task');
const docsTasks = tasks.filter(t => /docs/i.test(t.title ?? ''));
for (const t of docsTasks) update(t, (o) => { o.status = 'done'; });
await flush();

const after = await query('com.example.type.task');
const done = after.filter(t => t.status === 'done');
print('closed now:', docsTasks.map(t => t.title).join(', '));
print('done total:', done.length, 'of', after.length);
for (const t of after) print(`${t.title}: ${t.status}`);
